/* ══════════════════════════════════════════
   LANDING PAGE
══════════════════════════════════════════ */
function initMarquee() {
  const items = BRANDS.map(b => brandMark(b, 46));
  const base = [...items, ...items, ...items];
  const full = [...base, ...base];
  const el = document.getElementById('marquee');
  if (el) el.innerHTML = full.join('');
}

// Brand logo image (falls back to the name as text when a brand has no logo).
// `base` = height in px for a 4:1 logo; fitLogo() scales others so wide and
// compact logos look equally heavy.
function brandMark(b, base) {
  return b.logo
    ? `<img class="brand-logo" src="${b.logo}" alt="${b.name}" style="height:${base}px" onload="fitLogo(this, ${base})">`
    : `<span>${b.name}</span>`;
}
function fitLogo(img, base) {
  const aspect = img.naturalWidth / img.naturalHeight;
  if (aspect) img.style.height = Math.round(base * Math.min(1.6, Math.sqrt(4 / aspect))) + 'px';
}

function initViz() {
  const canvas = document.getElementById('viz-canvas');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  let w, h, dpr;
  function resize() {
    dpr = Math.min(window.devicePixelRatio || 1, 2);
    w = canvas.clientWidth; h = canvas.clientHeight;
    canvas.width = w * dpr; canvas.height = h * dpr;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  }
  resize();
  window.addEventListener('resize', resize);

  const reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  const barCount = 72;
  const seeds = Array.from({length: barCount}, () => Math.random() * Math.PI * 2);

  function accentColor() {
    return '#d8b26a'; // landing is always dark — fixed champagne gold
  }

  function draw(t) {
    ctx.clearRect(0, 0, w, h);
    const bw = w / barCount;
    const baseY = h;
    const col = accentColor();
    for (let i = 0; i < barCount; i++) {
      const phase = seeds[i];
      const n = (Math.sin(t * 0.002 + phase) * 0.5 + 0.5)
              * (Math.sin(t * 0.0013 + phase * 1.7) * 0.5 + 0.5);
      const amp = reduce ? (Math.sin(phase) * 0.5 + 0.5) : n;
      const bh = 16 + amp * (h * 0.4);
      const x = i * bw;
      const grad = ctx.createLinearGradient(0, baseY - bh, 0, baseY);
      grad.addColorStop(0, col);
      grad.addColorStop(1, 'transparent');
      ctx.globalAlpha = 0.14 + amp * 0.2;
      ctx.fillStyle = grad;
      ctx.fillRect(x + bw * 0.22, baseY - bh, bw * 0.56, bh);
    }
    ctx.globalAlpha = 1;
    if (!reduce) requestAnimationFrame(draw);
  }
  if (reduce) draw(0); else requestAnimationFrame(draw);
}

function enterPortal() {
  const landing = document.getElementById('landing');
  const app = document.querySelector('.app');
  app.classList.remove('app-hidden');
  landing.classList.add('hidden-landing');
  setTimeout(() => { landing.hidden = true; }, 600);
  portalMusicStart();
}

/* ── Musik latar portal (30 Okt 2026, permintaan pemilik) ──
   Lagu = assets/audio/portal-music.mp3: musik lounge sintetis buatan sendiri (tools/backsound.py, tanpa sampel pihak lain → bebas royalti).
   Browser melarang suara sebelum ada klik, jadi musik mulai saat "Masuk Portal" ditekan (enterPortal) — atau klik pertama bila portal
   dibuka lewat link produk. Tombol 🔊/🔇 di topbar (toggleMusic), pilihan diingat di localStorage PORTAL_MUSIC_KEY ('off' = mati).
   Volume lewat Web Audio GainNode (iOS mengabaikan audio.volume); diam sementara saat video bersuara diputar & saat tab tidak aktif.
   Tidak berbunyi di layar videotron (?layar=qa). */
const PORTAL_MUSIC_SRC = 'assets/audio/portal-music.mp3?v=1', PORTAL_MUSIC_VOL = 0.22, PORTAL_MUSIC_KEY = 'cai-music';
const PM_ICON_ON = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M9 18V5l12-2v13"/><circle cx="6" cy="18" r="3"/><circle cx="18" cy="16" r="3"/></svg>';
const PM_ICON_OFF = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M9 18V5l12-2v13"/><circle cx="6" cy="18" r="3"/><circle cx="18" cy="16" r="3"/><line x1="3" y1="3" x2="21" y2="21"/></svg>';
let pm = null, pmWant = false, pmStopT = null, pmArmed = false;
function pmPref() { try { return localStorage.getItem(PORTAL_MUSIC_KEY) !== 'off'; } catch (e) { return true; } }
function pmIcon() {
  const b = document.getElementById('music-btn'); if (!b) return;
  const on = pmPref();
  b.innerHTML = on ? PM_ICON_ON : PM_ICON_OFF;
  b.title = b.ariaLabel = on ? 'Matikan musik latar' : 'Nyalakan musik latar';
  b.classList.toggle('music-off', !on);
}
const pmVideoOn = () => [...document.querySelectorAll('video')].some(v => !v.paused && !v.ended && !v.muted);
function pmSync() {
  if (QA_SCREEN_MODE) return;
  pmIcon();
  const should = pmWant && pmPref() && !document.hidden && !pmVideoOn();
  if (should) {
    if (!pm) {
      try {
        const el = new Audio(PORTAL_MUSIC_SRC); el.loop = true; el.preload = 'auto';
        const AC = window.AudioContext || window.webkitAudioContext;
        const ctx = AC ? new AC() : null, gain = ctx ? ctx.createGain() : null;
        if (ctx) { gain.gain.value = 0; ctx.createMediaElementSource(el).connect(gain).connect(ctx.destination); } else el.volume = PORTAL_MUSIC_VOL;
        pm = { el, ctx, gain };
      } catch (e) { return; }
    }
    clearTimeout(pmStopT);
    pm.ctx?.resume?.();
    pm.el.play().then(() => {
      if (!pm.gain) return;
      const g = pm.gain.gain, t = pm.ctx.currentTime;
      g.cancelScheduledValues(t); g.setValueAtTime(g.value, t); g.linearRampToValueAtTime(PORTAL_MUSIC_VOL, t + 1.8);
    }).catch(() => pmArm());   // ditolak browser → tunggu klik berikutnya
  } else if (pm && !pm.el.paused) {
    clearTimeout(pmStopT);
    if (pm.gain) {
      const g = pm.gain.gain, t = pm.ctx.currentTime;
      g.cancelScheduledValues(t); g.setValueAtTime(g.value, t); g.linearRampToValueAtTime(0, t + 0.7);
      pmStopT = setTimeout(() => pm.el.pause(), 750);
    } else pm.el.pause();
  }
}
function portalMusicStart() { pmWant = true; pmSync(); }
function toggleMusic() {
  const on = !pmPref();
  try { localStorage.setItem(PORTAL_MUSIC_KEY, on ? 'on' : 'off'); } catch (e) {}
  pmWant = true; pmSync();
  showToast(on ? '🎵 Musik latar menyala' : '🔇 Musik latar dimatikan');
}
// Portal dibuka tanpa landing (link produk) / play ditolak: mulai pada klik atau tombol pertama di dalam portal
function pmArm() {
  if (pmArmed || QA_SCREEN_MODE) return;
  pmArmed = true;
  const go = e => {
    if (!document.getElementById('landing')?.hidden && !document.querySelector('.app:not(.app-hidden)')) return;
    if (e.target?.closest?.('#music-btn')) return;
    ['pointerdown', 'keydown'].forEach(ev => document.removeEventListener(ev, go, true));
    pmArmed = false;
    portalMusicStart();
  };
  ['pointerdown', 'keydown'].forEach(ev => document.addEventListener(ev, go, true));
}
['play', 'pause', 'ended', 'volumechange'].forEach(ev => document.addEventListener(ev, e => { if (e.target?.tagName === 'VIDEO' && pmWant) pmSync(); }, true));
document.addEventListener('visibilitychange', () => { if (pmWant) pmSync(); });

