function openUpdates() {
  showView('updates');
  const el = document.getElementById('updates-list');
  if (el.children.length) return;

  const typeIcon = { video:'🎬', photo:'🖼️', data:'📋' };
  const typeLabel = { video:'Video', photo:'Foto', data:'Data' };
  const typeColor = { video:'#e67e22', photo:'#27ae60', data:'#2980b9' };

  // Kelompokkan per tanggal
  const byDate = new Map();
  RECENT_UPDATES.forEach(u => {
    if (!byDate.has(u.date)) byDate.set(u.date, []);
    byDate.get(u.date).push(u);
  });

  let html = '<div style="padding-top:28px;display:flex;flex-direction:column;gap:28px">';
  byDate.forEach((updates, date) => {
    const d = new Date(date + 'T00:00:00+07:00');
    const label = d.toLocaleDateString('id-ID', { day:'numeric', month:'long', year:'numeric', timeZone:'Asia/Jakarta' });
    html += `<div>
      <div style="font-size:11px;font-family:var(--f-mono);color:var(--accent);letter-spacing:.12em;font-weight:700;text-transform:uppercase;margin-bottom:12px">${label}</div>
      <div style="display:flex;flex-direction:column;gap:8px">`;
    updates.forEach(u => {
      const { brand, product } = findProduct(u.brandId, u.productId);
      if (!brand || !product) return;
      const col = typeColor[u.type] || 'var(--accent)';
      const ic = typeIcon[u.type] || '•';
      const lbl = typeLabel[u.type] || u.type;
      html += `<div onclick="showProduct('${u.brandId}','${u.productId}')" style="display:flex;align-items:center;gap:14px;padding:12px 16px;border-radius:10px;border:1px solid var(--border);background:var(--surface);cursor:pointer;transition:background .15s" onmouseenter="this.style.background='var(--glass-bar)'" onmouseleave="this.style.background='var(--surface)'">
        <span style="font-size:18px;flex-shrink:0">${ic}</span>
        <div style="flex:1;min-width:0">
          <div style="font-size:13px;font-weight:600;color:var(--fg);white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${product.name}</div>
          <div style="font-size:11px;color:var(--fg-muted);margin-top:2px">${brand.name} · ${u.note}</div>
        </div>
        <span style="font-size:9px;font-family:var(--f-mono);font-weight:700;letter-spacing:.08em;padding:3px 8px;border-radius:4px;background:${col}22;color:${col};border:1px solid ${col}44;flex-shrink:0">${lbl.toUpperCase()}</span>
      </div>`;
    });
    html += `</div></div>`;
  });
  html += '</div>';
  el.innerHTML = html;
}

function openBrandsPhilosophy() {
  showView('brands');
  const grid = document.getElementById('brands-philosophy-grid');
  if (grid.children.length) return;
  grid.style.cssText = 'display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr));gap:20px;padding:28px 0 48px';
  grid.innerHTML = BRANDS.map((b) => {
    const logoHtml = b.logo
      ? `<img src="${b.logo}" alt="${b.name}" style="max-height:48px;max-width:180px;width:auto;object-fit:contain;display:block" onload="fitLogo(this,48)">`
      : `<span style="font-size:22px;font-weight:800;color:#fff;font-family:var(--f-display)">${b.name}</span>`;
    return `<div class="bp-card" onclick="showBrand('${b.id}')" style="cursor:pointer;border-radius:14px;overflow:hidden;border:1px solid var(--border);transition:transform .2s,box-shadow .2s">
      <!-- Header: brand gradient bg + logo -->
      <div style="background:${b.bg};padding:32px 28px 28px;display:flex;flex-direction:column;gap:16px;min-height:140px;justify-content:flex-end;position:relative">
        <div style="position:absolute;top:0;left:0;right:0;height:3px;background:${b.color};border-radius:14px 14px 0 0"></div>
        ${logoHtml}
        <div style="font-size:9px;font-family:var(--f-mono);color:${b.color};letter-spacing:.12em;font-weight:600;opacity:.85;text-transform:uppercase">${b.tagline}</div>
      </div>
      <!-- Body: desc + CTA -->
      <div style="background:var(--surface);padding:20px 24px 22px;display:flex;flex-direction:column;gap:14px">
        <div style="font-size:13px;line-height:1.75;color:var(--fg-muted);display:flex;flex-direction:column;gap:10px">${(b.philosophy||b.desc).split('\n\n').map(p=>`<p style="margin:0">${p}</p>`).join('')}</div>
        <div style="display:flex;align-items:center;gap:8px">
          <div style="width:20px;height:2px;background:${b.color};border-radius:2px;transition:width .25s" class="bp-line"></div>
          <span style="font-size:10px;font-family:var(--f-mono);color:${b.color};font-weight:700;letter-spacing:.1em">LIHAT PRODUK</span>
        </div>
      </div>
    </div>`;
  }).join('');

  document.querySelectorAll('.bp-card').forEach(card => {
    const line = card.querySelector('.bp-line');
    card.addEventListener('mouseenter', () => { card.style.transform='translateY(-3px)'; card.style.boxShadow='0 8px 32px rgba(0,0,0,.35)'; if(line) line.style.width='36px'; });
    card.addEventListener('mouseleave', () => { card.style.transform=''; card.style.boxShadow=''; if(line) line.style.width='20px'; });
  });
}

function backToLanding() {
  const landing = document.getElementById('landing');
  const app = document.querySelector('.app');
  landing.hidden = false;
  // reflow so the fade-in transition runs
  void landing.offsetWidth;
  landing.classList.remove('hidden-landing');
  app.classList.add('app-hidden');
  // reset portal to dashboard for next entry
  showView('dashboard');
  window.scrollTo(0, 0);
}

