function showBrand(brandId) {
  currentBrandId = brandId;
  activeFilter = 'Semua';
  const brand = BRANDS.find(b => b.id === brandId);
  if (!brand) return;

  // Hero
  document.getElementById('brand-hero').style.background = brand.bg;
  document.getElementById('brand-hero-name').style.color = brand.text;
  document.getElementById('brand-hero-tagline').style.color = brand.text;
  const heroName = document.getElementById('brand-hero-name');
  if (brand.logo) heroName.innerHTML = brandMark(brand, 46);
  else heroName.textContent = brand.name;
  document.getElementById('brand-hero-tagline').textContent = brand.tagline;

  // Sidebar active
  document.querySelectorAll('.sidebar-item, .brand-nav-item').forEach(el => el.classList.remove('active'));
  document.getElementById('nav-brand-' + brandId)?.classList.add('active');
  // Mobile nav active
  document.querySelectorAll('.mobile-nav-item').forEach(el => el.classList.remove('active'));
  document.getElementById('mnav-brands')?.classList.add('active');

  // Filters (by category)
  const cats = ['Semua', ...brandCategories(brand)];
  document.getElementById('product-filters').innerHTML = cats.map(c =>
    `<button class="filter-chip${c==='Semua'?' active':''}" onclick="filterProducts('${c}','${brandId}')">${c}</button>`
  ).join('');

  renderProducts(brand, 'Semua');

  hideViews();
  document.getElementById('view-brand').classList.add('active');
  document.querySelector('.main')?.scrollTo(0, 0);
}

function filterProducts(cat, brandId) {
  activeFilter = cat;
  document.querySelectorAll('.filter-chip').forEach(el => {
    el.classList.toggle('active', el.textContent === cat);
  });
  const brand = BRANDS.find(b => b.id === brandId || b.id === currentBrandId);
  if (brand) renderProducts(brand, cat);
}

// Harga jual umum (SRP) opsional per produk: `price` (angka rupiah) + `priceUnit` opsional ('set', 'pcs', 'pair', …)
const fmtRp = n => 'Rp ' + Number(n).toLocaleString('id-ID');
// SRP: `price` (satu harga) atau `priceList` ({ varian: harga }, mis. kabel per panjang → tampil "mulai Rp …")
const hasPrice = p => !!(p.price || (p.priceList && Object.keys(p.priceList).length));
const unitText = p => p.priceUnit ? ' / ' + p.priceUnit : '';
// EOL (End of Line): produk tidak diproduksi lagi, dijual selama stok masih ada → field `eol:true`
const EOL_TITLE = 'End of Line — tidak diproduksi lagi, selama stok masih ada';
const SOON_TITLE = 'Produk baru — segera hadir (coming soon)';
const eolTag = p => (p.eol ? `<span class="eol-tag" title="${EOL_TITLE}">EOL</span>` : '')
  + (p.soon ? `<span class="eol-tag soon-tag" title="${SOON_TITLE}">COMING SOON</span>` : '');   // soon:true = produk baru belum rilis
const srpFrom = p => !p.price && hasPrice(p);
const srpAmount = p => p.price || (hasPrice(p) ? Math.min(...Object.values(p.priceList)) : 0);
const srpText = p => hasPrice(p) ? (srpFrom(p) ? 'mulai ' : '') + fmtRp(srpAmount(p)) + unitText(p) : '';
// Baris harga di kartu produk: label kecil di kiri, harga di kanan (tidak berebut tempat dengan nama)
const srpRow = p => hasPrice(p) ? `<div class="product-price-row" title="Harga jual (SRP)"><span class="pp-tag">${srpFrom(p) ? 'Mulai' : 'SRP'}</span><span class="product-price">${fmtRp(srpAmount(p))}${p.priceUnit ? `<small> / ${p.priceUnit}</small>` : ''}</span></div>` : '';

function productCard(brand, p) {
  const photo = p.photo
    ? `<img class="product-photo" src="${p.photo}" alt="${p.name}" loading="lazy">`
    : `<span class="product-thumb-icon">${p.emoji}</span>`;
  const sb = stockBadgeSmall(p.id);
  return `
    <div class="product-card" onclick="showProduct('${brand.id}','${p.id}')">
      <div class="product-thumb" style="background:${p.photo ? '#fff' : brand.color + '10'};position:relative">
        ${photo}
        <span class="product-thumb-label">${p.category}</span>
        ${p.hasVideo ? `<span class="video-badge">▶ VIDEO</span>` : ''}
        ${sb ? `<span class="product-stock-badge ${sb.cls}">${sb.label}</span>` : ''}
      </div>
      <div class="product-info">
        <div class="product-name">${p.name}${eolTag(p)}</div>
        <div class="product-model">${p.model}</div>
        ${srpRow(p)}
      </div>
    </div>`;
}

function renderProducts(brand, filter) {
  const grid = document.getElementById('products-grid');
  // Render grouped by line; hide empty lines when filtered
  let html = '';
  brand.lines.forEach(line => {
    const items = filter === 'Semua' ? line.products : line.products.filter(p => p.category === filter);
    if (!items.length) return;
    html += `<div class="line-group">
      <div class="line-header"><span class="line-name">${line.name}</span><span class="line-count">${items.length}</span></div>
      <div class="line-grid">${items.map(p => productCard(brand, p)).join('')}</div>
    </div>`;
  });
  grid.innerHTML = html || `<div style="padding:20px;color:var(--fg-muted)">Tidak ada produk pada kategori ini.</div>`;
}

/* ══════════════════════════════════════════
   SEMUA BRAND — Katalog lengkap + pencarian
══════════════════════════════════════════ */
function openCatalog() {
  catalogBrand = 'all';
  const chips = document.getElementById('catalog-brand-chips');
  chips.innerHTML = [{id:'all',name:'Semua'}, ...BRANDS.map(b=>({id:b.id,name:b.name}))].map(b =>
    `<button class="filter-chip${b.id==='all'?' active':''}" data-brand="${b.id}" onclick="setCatalogBrand('${b.id}')">${b.name}</button>`
  ).join('');
  const search = document.getElementById('catalog-search');
  if (search) search.value = '';
  renderCatalog();
  showView('catalog');
  document.querySelector('.main')?.scrollTo(0, 0);
}

function setCatalogBrand(id) {
  catalogBrand = id;
  document.querySelectorAll('#catalog-brand-chips .filter-chip').forEach(el =>
    el.classList.toggle('active', el.dataset.brand === id));
  renderCatalog();
}

function renderCatalog() {
  const q = (document.getElementById('catalog-search')?.value || '').trim().toLowerCase();
  const filterBrand = catalogBrand !== 'all';
  const brands = filterBrand ? BRANDS.filter(b => b.id === catalogBrand) : BRANDS;

  // Flatten semua produk dengan info brand-nya
  const allPairs = [];
  brands.forEach(brand => brand.lines.forEach(l => l.products.forEach(p => allPairs.push({ brand, p }))));

  // Filter pencarian
  const filtered = allPairs.filter(({ brand, p }) => {
    if (!q) return true;
    return (p.name + ' ' + p.model + ' ' + p.category + ' ' + brand.name + ' ' + (p.desc||'')).toLowerCase().includes(q);
  });

  // Urutkan: ikuti UPDATE_LOG (terbaru dulu), sisanya di belakang
  if (!filterBrand && !q) {
    filtered.sort((a, b) => {
      const ia = UPDATE_LOG.indexOf(a.p.id);
      const ib = UPDATE_LOG.indexOf(b.p.id);
      const ra = ia === -1 ? 9999 : ia;
      const rb = ib === -1 ? 9999 : ib;
      return ra - rb;
    });
  }

  let html = '';
  if (!filterBrand && !q) {
    // Tampilkan sebagai flat grid dengan badge "Terbaru" untuk N produk pertama
    const recentCount = UPDATE_LOG.length;
    html = `<div class="line-grid">` + filtered.map(({ brand, p }, i) => {
      const badge = i < recentCount && UPDATE_LOG.includes(p.id)
        ? `<span style="position:absolute;top:8px;right:8px;background:var(--accent);color:#000;font-size:9px;font-weight:700;padding:2px 6px;border-radius:4px;letter-spacing:.05em;z-index:1">#${i+1}</span>`
        : '';
      return `<div style="position:relative">${badge}${productCard(brand, p)}</div>`;
    }).join('') + `</div>`;
  } else {
    // Tampilkan per brand (mode lama) saat ada filter
    const grouped = new Map();
    filtered.forEach(({ brand, p }) => {
      if (!grouped.has(brand.id)) grouped.set(brand.id, { brand, products: [] });
      grouped.get(brand.id).products.push(p);
    });
    grouped.forEach(({ brand, products }) => {
      html += `<div class="catalog-brand-block">
        <div class="catalog-brand-head">
          <span class="catalog-brand-dot" style="background:${brand.color}"></span>
          <span class="catalog-brand-name">${brand.name}</span>
          <span class="line-count">${products.length}</span>
          <button class="catalog-open-brand" onclick="showBrand('${brand.id}')">Buka brand →</button>
        </div>
        <div class="line-grid">${products.map(p => productCard(brand, p)).join('')}</div>
      </div>`;
    });
  }

  document.getElementById('catalog-results').innerHTML = html ||
    `<div style="padding:30px;color:var(--fg-muted);text-align:center">Tidak ada produk yang cocok dengan pencarian.</div>`;
  const cnt = document.getElementById('catalog-count');
  if (cnt) cnt.textContent = `${filtered.length} produk${q ? ' ditemukan untuk "' + q + '"' : (!filterBrand ? ' · diurutkan terbaru' : '')}`;
}

// Kembali dari detail produk ke halaman asal (katalog/brand/stok/…) di posisi scroll yang sama, tanpa merender ulang (30 Okt 2026, permintaan pemilik).
// Tombol back HP / browser juga kembali ke halaman asal (history.pushState saat detail produk dibuka).
let productFrom = null;
const PRODUCT_FROM_LABEL = { catalog: 'Katalog', stock: 'Stok Produk', rakit: 'Rakitan Audio', updates: 'Update Terbaru', dashboard: 'Dashboard' };
function showProduct(brandId, productId) {
  const curView = document.querySelector('.view.active');
  if (curView && curView.id !== 'view-product') {
    const main = document.querySelector('.main');
    productFrom = { el: curView, view: document.body.dataset.view, mainTop: main ? main.scrollTop : 0, winY: window.scrollY };
    try { if (!history.state?.pd) history.pushState({ pd: 1 }, '', location.href); } catch (e) {}
  }
  currentProductId = productId;
  currentBrandId = brandId;
  const { brand, line, product } = findProduct(brandId, productId);
  if (!brand || !product) return;

  const fromId = productFrom?.el?.id?.replace('view-', '');
  document.getElementById('product-back-label').textContent = (fromId && fromId !== 'brand' && PRODUCT_FROM_LABEL[fromId]) || brand.name;
  document.getElementById('panel-brand').textContent = brand.name + (line ? ' · ' + line : '');
  document.getElementById('panel-name').innerHTML = escHtml(product.name) + eolTag(product)
    + (product.eol ? `<div class="eol-note">${EOL_TITLE}</div>` : '')
    + (product.soon ? `<div class="eol-note soon-note">${SOON_TITLE}</div>` : '');
  document.getElementById('panel-model').textContent = product.model;
  const pp = document.getElementById('panel-price');
  pp.hidden = !hasPrice(product);
  pp.innerHTML = !hasPrice(product) ? '' : product.price || !product.priceList
    ? `${srpText(product)}<span>Harga jual (SRP)</span>`
    : `<span class="pp-label">Harga jual (SRP)</span><div class="pp-list">${Object.entries(product.priceList)
        .map(([k, v]) => `<div><b>${escHtml(k)}</b>${fmtRp(v)}${unitText(product)}<span class="pp-stk" data-v="${escHtml(k)}"></span></div>`).join('')}</div>`;

  // Main media
  const mediaMain = document.getElementById('media-main');
  if (product.photo) {
    mediaMain.innerHTML = `<img src="${product.photo}" alt="${product.name}" style="width:100%;height:100%;object-fit:contain">`;
    mediaMain.style.background = '#fff';
  } else {
    mediaMain.innerHTML = `<span>${product.emoji}</span>`;
    mediaMain.style.background = `${brand.color}10`;
  }

  // Thumbnails — one per photo, then video, then pdf
  const photos = product.photos || (product.photo ? [product.photo] : ['']);
  const thumbData = [
    ...photos.map((src, i) => ({label:'Foto ' + (i + 1), type:'photo', src})),
    ...(product.hasVideo ? [{label:'Video', type:'video'}] : []),
    ...(product.pdf ? [{label:'Panduan', type:'pdf', src: product.pdf}] : []),
  ];   // thumbnail 'Spek' (ikon grafik 📊) dihapus 25 Okt 2026 atas permintaan pemilik
  document.getElementById('media-thumbs').innerHTML = thumbData.map((t,i) => `
    <div class="media-thumb${i===0?' active':''}" onclick="selectMedia(this,'${t.type}','${product.emoji}','${brand.color}','${t.label}','${t.src || ''}')">
      ${t.type==='photo' && t.src ? `<img src="${t.src}" alt="" style="width:100%;height:100%;object-fit:cover">`
        : t.type==='video' && product.videoPoster ? `<img src="${product.videoPoster}" alt="" style="width:100%;height:100%;object-fit:cover">`
        : t.type==='pdf' ? `<div style="display:flex;flex-direction:column;align-items:center;justify-content:center;height:100%;gap:3px"><span style="font-size:20px">📄</span><span style="font-size:8px;font-weight:700;letter-spacing:.05em;color:var(--fg-muted)">PDF</span></div>`
        : `<span>${t.type==='video'?'🎬':t.type==='doc'?'📊':product.emoji}</span>`}
      ${t.type==='video'?`<div class="play-icon"><svg viewBox="0 0 10 10"><polygon points="2,1 9,5 2,9"/></svg></div>`:''}
    </div>
  `).join('');

  // Specs
  document.getElementById('specs-list').innerHTML = Object.entries(product.specs).map(([k,v]) =>
    `<div class="spec-row"><span class="spec-key">${k}</span><span class="spec-val">${v}</span></div>`
  ).join('') || `<div class="spec-row"><span class="spec-key">Spesifikasi lengkap menyusul</span></div>`;

  // Tags (category + line)
  const tags = [product.category, line].filter(Boolean);
  document.getElementById('panel-tags').innerHTML = tags.map(t =>
    `<span class="tag" style="color:${brand.color};border-color:${brand.color}40">${t}</span>`
  ).join('');

  // Stock badge in detail panel
  renderProductStockBadge(product.id);

  hideViews();
  document.getElementById('view-product').classList.add('active');
  document.querySelector('.main')?.scrollTo(0, 0);
}

function selectMedia(el, type, emoji, color, label, photo) {
  document.querySelectorAll('.media-thumb').forEach(t => t.classList.remove('active'));
  el.classList.add('active');
  const main = document.getElementById('media-main');
  const labelMap = {photo:'📷 Foto Produk', video:'▶ Video Demo', pdf:'📄 Panduan PDF', doc:'📊 Spec Sheet'};
  if (type === 'photo' && photo) {
    main.style.background = '#fff';
    main.innerHTML = `<img src="${photo}" alt="" style="width:100%;height:100%;object-fit:contain">`;
    return;
  }
  if (type === 'pdf' && photo) {
    main.style.background = '#f5f5f5';
    main.innerHTML = `
      <iframe src="${photo}" style="width:100%;height:100%;border:none" title="Panduan PDF"></iframe>
      <a href="${photo}" download style="position:absolute;bottom:14px;right:14px;background:var(--accent);color:#111;padding:6px 16px;border-radius:6px;font-size:11px;font-weight:800;letter-spacing:.05em;text-decoration:none;z-index:2">⬇ Download</a>`;
    return;
  }
  const video = type === 'video' && currentProduct().product?.video;
  if (video) {
    const poster = currentProduct().product.videoPoster;
    main.style.background = '#000';
    main.innerHTML = `<video src="${video}"${poster ? ` poster="${poster}"` : ''} controls playsinline preload="metadata" style="width:100%;height:100%;object-fit:contain"></video>
      <button class="media-share" onclick="shareVideo()" title="Kirim link video ini lewat WhatsApp">${WA_ICON}Bagikan</button>`;
    main.querySelector('video').play().catch(() => {});
    return;
  }
  const bgMap = {photo: `${color}10`, video:'#0a0a0a', pdf:'#f5f5f5', doc:'var(--surface2)'};
  main.style.background = bgMap[type] || 'var(--surface2)';
  main.innerHTML = `
    <span>${type==='video'?'▶':type==='doc'?'📊':emoji}</span>
    ${type==='video'?`<div style="position:absolute;bottom:18px;left:0;right:0;text-align:center;color:rgba(255,255,255,.6);font-size:12px">Video demo produk</div>`:''}
  `;
}

function backToBrand() {
  if (history.state?.pd) { history.back(); return; }   // popstate → productGoBack()
  productGoBack();
}
function productGoBack() {
  const f = productFrom; productFrom = null;
  if (!f || !document.body.contains(f.el)) { if (currentBrandId) showBrand(currentBrandId); return; }
  hideViews();
  f.el.classList.add('active');
  if (f.view) document.body.dataset.view = f.view;
  const main = document.querySelector('.main');
  requestAnimationFrame(() => { if (main) main.scrollTop = f.mainTop; window.scrollTo(0, f.winY); });
}
addEventListener('popstate', () => {
  if (document.getElementById('view-product')?.classList.contains('active')) productGoBack();
});

/* ══════════════════════════════════════════
   SPEC SHEET / PDF
══════════════════════════════════════════ */
function currentProduct() {
  return findProduct(currentBrandId, currentProductId);
}

// Darken/lighten a hex color by amt (-255..255)
function shade(hex, amt) {
  const n = parseInt(hex.slice(1), 16);
  let r = (n >> 16) + amt, g = ((n >> 8) & 255) + amt, b = (n & 255) + amt;
  r = Math.max(0, Math.min(255, r));
  g = Math.max(0, Math.min(255, g));
  b = Math.max(0, Math.min(255, b));
  return '#' + ((1 << 24) + (r << 16) + (g << 8) + b).toString(16).slice(1);
}

// Build a placeholder product photo as a JPEG data URL (real photos replace this)
function makePhotoPlaceholder(brand, product, idx, wmm, hmm) {
  const scale = 4;
  const w = Math.round(wmm * scale), h = Math.round(hmm * scale);
  const c = document.createElement('canvas');
  c.width = w; c.height = h;
  const g = c.getContext('2d');
  const grad = g.createLinearGradient(0, 0, w, h);
  grad.addColorStop(0, brand.color);
  grad.addColorStop(1, shade(brand.color, -36));
  g.fillStyle = grad; g.fillRect(0, 0, w, h);
  g.textAlign = 'center';
  g.fillStyle = 'rgba(255,255,255,.92)';
  g.font = 'bold ' + Math.round(h * 0.13) + 'px Arial, sans-serif';
  g.fillText(product.name, w / 2, h * 0.48);
  g.fillStyle = 'rgba(255,255,255,.65)';
  g.font = Math.round(h * 0.08) + 'px Arial, sans-serif';
  g.fillText('FOTO ' + idx, w / 2, h * 0.72);
  return c.toDataURL('image/jpeg', 0.9);
}

// Real product photo as JPEG data URL, read from the already-loaded spec sheet preview.
// Returns null when unavailable (no photo, not loaded yet, or canvas blocked under file://).
function productPhotoData(product) {
  if (!product.photo) return null;
  const img = document.querySelector('.sheet-photo-main img');
  if (!img || !img.complete || !img.naturalWidth) return null;
  try {
    const c = document.createElement('canvas');
    c.width = img.naturalWidth; c.height = img.naturalHeight;
    const g = c.getContext('2d');
    g.fillStyle = '#fff'; g.fillRect(0, 0, c.width, c.height);
    g.drawImage(img, 0, 0);
    return { data: c.toDataURL('image/jpeg', 0.9), w: c.width, h: c.height };
  } catch (e) { return null; }
}

function openSpecSheet() {
  const { brand, product } = currentProduct();
  if (!brand || !product) return;
  const today = new Date().toLocaleDateString('id-ID', { day:'numeric', month:'long', year:'numeric' });
  const { line } = currentProduct();
  const specsHtml = Object.entries(product.specs).map(([k,v]) =>
    `<div class="sheet-spec"><span class="k">${k}</span><span class="v">${v}</span></div>`).join('');
  const tags = [product.category, line].filter(Boolean);
  const tagsHtml = tags.map(t => `<span class="sheet-tag">${t}</span>`).join('');
  const photosHtml = product.photo
    ? `<div class="sheet-photo-main"><img src="${product.photo}" alt="${product.name}"></div>`
    : `<div class="sheet-photos">${[1,2,3].map(i => `<div class="sheet-photo" style="background:linear-gradient(135deg,${brand.color},${shade(brand.color,-32)})"><span>${product.emoji}</span><em>Foto ${i}</em></div>`).join('')}</div>`;

  document.getElementById('sheet-content').innerHTML = `
    <div class="sheet-accent"></div>
    <div class="sheet-body">
      <div class="sheet-top">
        <img src="${LOGO_NAVY}" alt="Concerto Audio Indonesia" style="height:30px;width:auto">
        <div class="sheet-doc-type">Spec Sheet</div>
      </div>
      <div class="sheet-brand">${brand.name}${line ? ' · ' + line : ''}</div>
      <div class="sheet-name">${product.name}</div>
      <div class="sheet-model">${product.model} &nbsp;·&nbsp; ${product.category}</div>
      <div class="sheet-section-title">Foto Produk</div>
      ${photosHtml}
      ${product.desc ? `<div class="sheet-desc">${product.desc}</div>` : ''}
      <div class="sheet-section-title">Spesifikasi Teknis</div>
      ${specsHtml}
      <div class="sheet-tags" style="margin-top:18px">${tagsHtml}</div>
      <div class="sheet-footer">
        <span>Distributor Resmi — Concerto Audio Indonesia</span>
        <span>${today}</span>
      </div>
    </div>
    <div class="sheet-actions">
      <button class="sheet-btn ghost" onclick="closeSpecSheet()">Tutup</button>
      <button class="sheet-btn primary" onclick="downloadPdf()">Unduh PDF</button>
    </div>
    <div class="sheet-note">Pratinjau di atas adalah isi file PDF, lengkap dengan foto. Slot foto terisi otomatis saat foto asli dimasukkan; unduhan berjalan penuh saat sistem di-deploy ke website.</div>
  `;
  document.getElementById('spec-modal').classList.add('open');
}

function closeSpecSheet() {
  document.getElementById('spec-modal').classList.remove('open');
}

function downloadPdf() {
  const { brand, product } = currentProduct();
  if (!brand || !product) return;
  if (!window.jspdf) return;
  try {
    const { jsPDF } = window.jspdf;
    const doc = new jsPDF({ unit:'mm', format:'a4' });

    // accent bar
    doc.setFillColor(200,147,58); doc.rect(0, 0, 210, 5, 'F');

    // header — brand logo + doc type
    try { doc.addImage(LOGO_NAVY, 'PNG', 15, 11, 34, 34 * 59 / 174); } catch (err) {}
    doc.setFont('helvetica','bold'); doc.setFontSize(9); doc.setTextColor(183,135,58);
    doc.text('SPEC SHEET', 195, 20, { align:'right' });

    // title block
    doc.setFontSize(10); doc.setTextColor(183,135,58);
    doc.text(brand.name.toUpperCase(), 15, 38);
    doc.setFont('helvetica','bold'); doc.setFontSize(24); doc.setTextColor(20,20,20);
    doc.text(product.name, 15, 48);
    doc.setFont('courier','normal'); doc.setFontSize(11); doc.setTextColor(130,130,130);
    doc.text(product.model + '   -   ' + product.category, 15, 55);

    // product photos
    let y = 66;
    doc.setFont('helvetica','bold'); doc.setFontSize(9); doc.setTextColor(150,150,150);
    doc.text('FOTO PRODUK', 15, y);
    y += 5;
    const imgW = 56, imgH = 42, gap = 6, startX = 15;
    const real = productPhotoData(product);
    if (real) {
      // real photo: centered "contain" inside a 180×64mm area
      const boxH = 64, s = Math.min(180 / real.w, boxH / real.h);
      const w = real.w * s, h = real.h * s;
      doc.addImage(real.data, 'JPEG', 15 + (180 - w) / 2, y + (boxH - h) / 2, w, h);
      y += boxH + 14;
    } else {
      for (let i = 0; i < 3; i++) {
        const data = makePhotoPlaceholder(brand, product, i + 1, imgW, imgH);
        doc.addImage(data, 'JPEG', startX + i * (imgW + gap), y, imgW, imgH);
      }
      y += imgH + 14;
    }

    // description
    if (product.desc) {
      doc.setFont('helvetica','italic'); doc.setFontSize(9.5); doc.setTextColor(90,90,90);
      const dl = doc.splitTextToSize(product.desc, 180);
      doc.text(dl, 15, y); y += dl.length * 5 + 6;
    }

    // specs
    doc.setFont('helvetica','bold'); doc.setFontSize(9); doc.setTextColor(150,150,150);
    doc.text('SPESIFIKASI TEKNIS', 15, y);
    y += 4; doc.setDrawColor(225,225,225); doc.line(15, y, 195, y); y += 8;
    Object.entries(product.specs).forEach(([k,v]) => {
      if (y > 275) { doc.addPage(); y = 25; }
      doc.setFont('helvetica','normal'); doc.setFontSize(10.5); doc.setTextColor(110,110,110);
      doc.text(String(k), 15, y);
      doc.setFont('helvetica','bold'); doc.setTextColor(25,25,25);
      doc.text(doc.splitTextToSize(String(v).replace(/Ω/g, 'Ohm'), 95), 195, y, { align:'right' });
      doc.setDrawColor(240,240,240); doc.line(15, y + 3, 195, y + 3);
      y += 8.5;
    });

    // tag line
    y += 4;
    const line = currentProduct().line;
    doc.setFont('helvetica','normal'); doc.setFontSize(9); doc.setTextColor(120,120,120);
    doc.text([product.category, line].filter(Boolean).join('   •   '), 15, y);

    // footer
    doc.setDrawColor(225,225,225); doc.line(15, 282, 195, 282);
    doc.setFont('helvetica','normal'); doc.setFontSize(8); doc.setTextColor(150,150,150);
    doc.text('Distributor Resmi — Concerto Audio Indonesia', 15, 288);
    const today = new Date().toLocaleDateString('id-ID', { day:'numeric', month:'long', year:'numeric' });
    doc.text(today, 195, 288, { align:'right' });

    doc.save(product.model.replace(/[^a-z0-9]/gi, '_') + '_Concerto.pdf');
  } catch (e) {
    /* download blocked in sandbox preview — modal already shows the content */
  }
}

document.addEventListener('keydown', function(e) {
  if (e.key === 'Escape') closeSpecSheet();
});

/* ══════════════════════════════════════════
   THEME TOGGLE (dark ⇄ light), persisted
══════════════════════════════════════════ */
const SUN_ICON = '<circle cx="12" cy="12" r="4.2"/><path d="M12 2v2M12 20v2M4.9 4.9l1.4 1.4M17.7 17.7l1.4 1.4M2 12h2M20 12h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"/>';
const MOON_ICON = '<path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z"/>';
function isLightTheme() {
  const t = document.documentElement.getAttribute('data-theme');
  if (t === 'light') return true;
  if (t === 'dark') return false;
  return window.matchMedia('(prefers-color-scheme: light)').matches;
}
function updateTopbarLogo() {
  const el = document.getElementById('logo-top-dark');
  if (el) el.src = isLightTheme() ? LOGO_NAVY : LOGO_WHITE;
}
function applyThemeIcon() {
  const icon = document.getElementById('theme-icon');
  if (icon) icon.innerHTML = isLightTheme() ? MOON_ICON : SUN_ICON;
  updateTopbarLogo();
}
function toggleTheme() {
  const next = isLightTheme() ? 'dark' : 'light';
  document.documentElement.setAttribute('data-theme', next);
  try { localStorage.setItem('cai-theme', next); } catch(e){}
  applyThemeIcon();
}
try {
  const saved = localStorage.getItem('cai-theme');
  if (saved === 'light' || saved === 'dark') document.documentElement.setAttribute('data-theme', saved);
} catch(e){}
applyThemeIcon();
